def f(g):
    H_=len(g); W_=len(g[0])
    out=[r[:] for r in g]
    four=[(i,j) for i,r in enumerate(g) for j,c in enumerate(r) if c==4]
    six=[(i,j) for i,r in enumerate(g) for j,c in enumerate(r) if c==6]
    rel=[(i-min(p[0] for p in four),j-min(p[1] for p in four)) for i,j in four]
    mh=max(i for i,_ in six)-min(i for i,_ in six)+1
    mw=max(j for _,j in six)-min(j for _,j in six)+1
    tf = 'fv' if mw<mh else 'fh'  # non-square -> below (vertical flip); square-ish -> beside (horizontal flip)
    q=tf(rel); tn=norm(q)
    if tf=='fv':
        tr=max(i for i,_ in four)+1; tc=min(j for _,j in four)
    else:
        tr=min(i for i,_ in four); tc=max(j for _,j in four)+1
    for a,b in tn:
        ii=a+tr; jj=b+tc
        if 0<=ii<H_ and 0<=jj<W_: out[ii][jj]=4
    for i,j in six: out[i][j]=0
    return out
