def objects(g,cols):
    seen=[[False]*len(g[0]) for _ in g]; objs=[]
    for i in range(len(g)):
        for j in range(len(g[0])):
            if g[i][j]==cols and not seen[i][j]:
                st=[(i,j)];seen[i][j]=True;cells=[]
                while st:
                    y,x=st.pop();cells.append((y,x))
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        yy,xx=y+dy,x+dx
                        if 0<=yy<len(g) and 0<=xx<len(g[0]) and g[yy][xx]==cols and not seen[yy][xx]:
                            seen[yy][xx]=True;st.append((yy,xx))
                objs.append(cells)
    return objs
